//! Prime-order curves over F_p (Go: curve.go).

use std::collections::HashMap;

use rand::rngs::StdRng;

use crate::field::{add_mod, inv_mod, is_prime, mul_mod, pow_mod, rand_below, sqrt_mod, sub_mod};
use crate::{Error, Result};

/// Curve is y^2 = x^3 + A x + B over F_P, with a group of prime order Order
/// generated by G. Plain data (Copy) so closures can own a copy.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct Curve {
    pub p: u64,
    pub a: u64,
    pub b: u64,
    pub order: u64,
    pub g: Point,
}

/// Point is an affine point; Inf marks the identity O.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Default)]
pub struct Point {
    pub x: u64,
    pub y: u64,
    pub inf: bool,
}

/// Infinity is the group identity.
pub const INFINITY: Point = Point {
    x: 0,
    y: 0,
    inf: true,
};

impl Curve {
    /// FieldBits is b = ceil(log2 p), the width of one coordinate
    /// (Go: bits.Len64(P-1)).
    pub fn field_bits(&self) -> usize {
        64 - (self.p - 1).leading_zeros() as usize
    }

    pub(crate) fn rhs(&self, x: u64) -> u64 {
        let p = self.p;
        let x3 = mul_mod(mul_mod(x, x, p), x, p);
        add_mod(add_mod(x3, mul_mod(self.a, x, p), p), self.b % p, p)
    }

    /// OnCurve reports whether pt is O or a valid affine point.
    pub fn on_curve(&self, pt: Point) -> bool {
        if pt.inf {
            return true;
        }
        if pt.x >= self.p || pt.y >= self.p {
            return false;
        }
        mul_mod(pt.y, pt.y, self.p) == self.rhs(pt.x)
    }

    pub fn neg(&self, pt: Point) -> Point {
        if pt.inf || pt.y == 0 {
            return pt;
        }
        Point {
            x: pt.x,
            y: self.p - pt.y,
            inf: false,
        }
    }

    /// Add returns s + t using the affine chord-and-tangent law.
    pub fn add(&self, s: Point, t: Point) -> Point {
        if s.inf {
            return t;
        }
        if t.inf {
            return s;
        }
        crate::opcount::bump(if s == t { "doubles" } else { "adds" }, 1);
        let p = self.p;
        let lambda = if s.x == t.x {
            if add_mod(s.y, t.y, p) == 0 {
                return INFINITY;
            }
            let num = add_mod(mul_mod(3, mul_mod(s.x, s.x, p), p), self.a % p, p);
            mul_mod(num, inv_mod(mul_mod(2, s.y, p), p), p)
        } else {
            mul_mod(sub_mod(t.y, s.y, p), inv_mod(sub_mod(t.x, s.x, p), p), p)
        };
        let x = sub_mod(sub_mod(mul_mod(lambda, lambda, p), s.x, p), t.x, p);
        let y = sub_mod(mul_mod(lambda, sub_mod(s.x, x, p), p), s.y, p);
        Point { x, y, inf: false }
    }

    /// Mul returns [k]pt.
    pub fn mul(&self, k: u64, pt: Point) -> Point {
        let mut acc = INFINITY;
        let n = 64 - k.leading_zeros() as i64;
        for i in (0..n).rev() {
            acc = self.add(acc, acc);
            if (k >> i) & 1 == 1 {
                acc = self.add(acc, pt);
            }
        }
        acc
    }

    /// Points enumerates every affine point of the curve (toy sizes only).
    pub fn points(&self) -> Vec<Point> {
        let p = self.p;
        let mut roots: HashMap<u64, u64> = HashMap::with_capacity((p / 2 + 1) as usize);
        for y in 0..=p / 2 {
            roots.insert(mul_mod(y, y, p), y);
        }
        let mut pts: Vec<Point> = Vec::with_capacity((p + 1) as usize);
        for x in 0..p {
            let y = match roots.get(&self.rhs(x)) {
                Some(&y) => y,
                None => continue,
            };
            pts.push(Point { x, y, inf: false });
            if y != 0 {
                pts.push(Point {
                    x,
                    y: p - y,
                    inf: false,
                });
            }
        }
        pts
    }

    /// WindowPoints enumerates the affine points with x < x_bound by taking
    /// the square root of x^3 + a x + b for each x (Go: WindowPoints). Its cost
    /// is about x_bound square-root tests, not the size of the group.
    pub fn window_points(&self, x_bound: u64) -> Vec<Point> {
        let p = self.p;
        let x_bound = x_bound.min(p);
        let mut pts: Vec<Point> = Vec::with_capacity((2 * x_bound) as usize);
        for x in 0..x_bound {
            let y = match sqrt_mod(self.rhs(x), p) {
                Some(y) => y,
                None => continue,
            };
            let y = if y != 0 && y > p - y { p - y } else { y };
            pts.push(Point { x, y, inf: false });
            if y != 0 {
                pts.push(Point {
                    x,
                    y: p - y,
                    inf: false,
                });
            }
        }
        pts
    }
}

/// RandomPrimeOrderCurve searches for a curve over a random b-bit prime field
/// whose group order is prime, by naive point counting. Toy sizes only.
/// Errors: "ecdl: field size must be between 4 and 26 bits for naive point
/// counting", "ecdl: no prime-order curve found".
pub fn random_prime_order_curve(rng: &mut StdRng, b: usize) -> Result<Curve> {
    if !(4..=26).contains(&b) {
        return Err(Error::new(
            "ecdl: field size must be between 4 and 26 bits for naive point counting",
        ));
    }
    let lo = 1u64 << (b - 1);
    for _tries in 0..100000 {
        let p = lo + rand_below(rng, lo);
        if p <= 3 || !is_prime(p) {
            continue;
        }
        let mut c = Curve {
            p,
            a: rand_below(rng, p),
            b: rand_below(rng, p),
            order: 0,
            g: Point::default(),
        };
        // 4a^3 + 27b^2 != 0 (mod p)
        let disc = add_mod(
            mul_mod(4, pow_mod(c.a, 3, p), p),
            mul_mod(27, mul_mod(c.b, c.b, p), p),
            p,
        );
        if disc == 0 {
            continue;
        }
        let pts = c.points();
        let n = pts.len() as u64 + 1;
        if !is_prime(n) {
            continue;
        }
        c.order = n;
        c.g = pts[rand_below(rng, pts.len() as u64) as usize];
        return Ok(c);
    }
    Err(Error::new("ecdl: no prime-order curve found"))
}
